"""Exercise the real GTK widgets under Xvfb, without Git or signing keys."""

import importlib.util
import io
import json
import os
from pathlib import Path
import subprocess
import sys
import time
import unittest

# Import the helper without leaving generated bytecode in the checkout.
sys.dont_write_bytecode = True
HELPER = Path(__file__).resolve().parents[1] / "scripts/host-rpc-handlers/git-review.py"
spec = importlib.util.spec_from_file_location("git_review", HELPER)
review = importlib.util.module_from_spec(spec)
spec.loader.exec_module(review)
Gtk, GLib, Gdk = review.Gtk, review.GLib, review.Gdk


class ReviewTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        if not Gtk.init_check():
            raise RuntimeError("GTK tests require an Xvfb display")

    def make_window(self, dry_run=False, timeout=120):
        payload = {
            "summary": "Repository: /trusted/repo\nBranch: main",
            "message": 'π 🐧 <script>never run()</script> & <b>literal</b>\n+not a diff',
            "diff": (
                "diff --git a/test b/test\nindex 123..456 100644\n--- a/test\n+++ b/test\n"
                "@@ -1,2 +1,2 @@\n-removed\n+added <img src='https://example.test/'>\n"
                "--- content beginning with two minus signs\n"
            ),
            "dryRun": dry_run,
        }
        window = review.ReviewWindow(payload, lambda: None, timeout)
        self.addCleanup(lambda: window.finish(1))
        return window, payload

    def contents(self, window):
        return window.buffer.get_text(*window.buffer.get_bounds(), True)

    def tags_at(self, window, text):
        offset = self.contents(window).index(text)
        return {
            tag.props.name for tag in window.buffer.get_iter_at_offset(offset).get_tags()
        }

    def pump_until(self, condition):
        deadline = time.monotonic() + 10
        context = GLib.MainContext.default()
        while not condition():
            if time.monotonic() >= deadline:
                self.fail("GTK event did not complete")
            context.iteration(False)
            time.sleep(0.001)

    def test_read_only_text_is_literal_selectable_and_copyable(self):
        window, payload = self.make_window()
        window.present()
        self.pump_until(window.view.get_mapped)
        self.assertFalse(window.view.get_editable())
        self.assertTrue(window.view.get_cursor_visible())
        self.assertTrue(window.view.get_monospace())
        text = self.contents(window)
        self.assertIn(payload["message"], text)
        self.assertIn(payload["diff"], text)
        start = text.index(payload["message"])
        begin = window.buffer.get_iter_at_offset(start)
        end = window.buffer.get_iter_at_offset(start + len(payload["message"]))
        window.buffer.select_range(begin, end)
        selection = window.buffer.get_selection_bounds()
        self.assertEqual(window.buffer.get_text(*selection, True), payload["message"])
        self.assertFalse(window.buffer.delete_interactive(begin, end, False))
        self.assertEqual(self.contents(window), text)
        window.view.emit("copy-clipboard")
        copied = []
        clipboard = window.view.get_clipboard()
        clipboard.read_text_async(
            None, lambda source, result: copied.append(source.read_text_finish(result))
        )
        self.pump_until(lambda: bool(copied))
        self.assertEqual(copied[0], payload["message"])

    def test_diff_colors_only_apply_to_diff_and_preserve_text(self):
        window, _ = self.make_window()
        self.assertEqual(self.tags_at(window, "+not a diff"), set())
        self.assertEqual(self.tags_at(window, "+++ b/test"), {"file"})
        self.assertEqual(self.tags_at(window, "@@ -1"), {"hunk"})
        self.assertEqual(self.tags_at(window, "-removed"), {"deletion"})
        self.assertEqual(self.tags_at(window, "+added"), {"addition"})
        self.assertEqual(self.tags_at(window, "--- content"), {"deletion"})
        table = window.buffer.get_tag_table()
        self.assertNotEqual(
            table.lookup("addition").props.foreground_rgba,
            table.lookup("deletion").props.foreground_rgba,
        )

    def test_approval_requires_checkbox_in_both_modes(self):
        for dry_run, label in ((False, "Commit"), (True, "Test")):
            window, _ = self.make_window(dry_run)
            self.assertEqual(window.confirm.get_label(), label)
            self.assertFalse(window.approval.get_active())
            self.assertFalse(window.confirm.get_sensitive())
            window.confirm.emit("clicked")
            self.assertIsNone(window.result)
            window.approval.set_active(True)
            self.assertTrue(window.confirm.get_sensitive())
            window.approval.set_active(False)
            self.assertFalse(window.confirm.get_sensitive())
            window.approval.set_active(True)
            window.confirm.emit("clicked")
            self.assertEqual(window.result, 0)

    def test_close_escape_and_cancel_decline(self):
        window, _ = self.make_window()
        window.present()
        window.close()
        self.assertEqual(window.result, 1)
        window, _ = self.make_window()
        handled = window.keys.emit("key-pressed", Gdk.KEY_Escape, 0, Gdk.ModifierType(0))
        self.assertTrue(handled)
        self.assertEqual(window.result, 1)
        window, _ = self.make_window()
        self.assertEqual(window.get_default_widget().get_label(), "Cancel")
        window.get_default_widget().emit("clicked")
        self.assertEqual(window.result, 1)

    def test_expiry_cannot_be_overridden_by_approval(self):
        window, _ = self.make_window(timeout=0.01)
        self.pump_until(lambda: window.result is not None)
        self.assertEqual(window.result, 5)
        window, _ = self.make_window()
        window.approval.set_active(True)
        window.deadline = time.monotonic() - 1
        window.confirm.emit("clicked")
        self.assertEqual(window.result, 5)

    def test_invalid_input_and_unavailable_display_fail_closed(self):
        window, payload = self.make_window()
        for invalid in (None, {}, {**payload, "dryRun": "false"}, {**payload, "diff": []}):
            with self.assertRaises(ValueError):
                review.read_review(io.BytesIO(json.dumps(invalid).encode()))
        result = subprocess.run(
            [sys.executable, "-I", str(HELPER)],
            input=json.dumps(payload),
            text=True,
            capture_output=True,
            env={**os.environ, "DISPLAY": "", "WAYLAND_DISPLAY": "", "GDK_BACKEND": "x11"},
            timeout=5,
        )
        self.assertEqual(result.returncode, 2)
        self.assertIn("Cannot open GTK display", result.stderr)
        self.assertEqual(result.stdout, "")


if __name__ == "__main__":
    unittest.main()
